cat > /tmp/a.py <<'E'
import ast,sys,glob
for f in sorted(glob.glob('billing/*.py')):
    t=ast.parse(open(f).read()); m=f[8:-3]
    def walk(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,ast.ClassDef): walk(c,pre+c.name+'.')
            elif isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                ann=ast.unparse(c.returns) if c.returns else '-'
                rets=[r for r in ast.walk(c) if isinstance(r,ast.Return)]
                vals=[ast.unparse(r.value) if r.value else 'BARE' for r in rets]
                print(f"{m}.{pre}{c.name} -> {ann} | {vals}")
                walk(c,pre+c.name+'.<l>.')
    walk(t,'')
E
.venv/bin/python -I /tmp/a.py | grep -v "^models.*TypedDict" | cut -c1-400
